package com.oreummok.nativeapp;
import android.graphics.*;import android.graphics.pdf.PdfDocument;import java.io.*;import java.util.*;
final class BusinessPdf {static byte[] create(String[] paragraphs)throws Exception{Paint paint=new Paint(3);paint.setColor(Color.rgb(23,53,43));paint.setTextSize(12);ArrayList<String> lines=new ArrayList<>();for(String raw:paragraphs){String rest=raw==null?"":raw;for(String segment:rest.split("\\n",-1)){if(segment.isEmpty()){lines.add("");continue;}while(!segment.isEmpty()){int n=paint.breakText(segment,true,515,null);if(n<1)n=1;if(n<segment.length()&&n>0&&Character.isHighSurrogate(segment.charAt(n-1)))n--;if(n<1)n=Math.min(2,segment.length());lines.add(segment.substring(0,n));segment=segment.substring(n);}}lines.add("");}int per=38,total=Math.max(1,(lines.size()+per-1)/per);if(total>200)throw new Exception("문서가 너무 깁니다. 메모를 줄이세요.");PdfDocument document=new PdfDocument();try{for(int page=0;page<total;page++){PdfDocument.Page p=document.startPage(new PdfDocument.PageInfo.Builder(595,842,page+1).create());Canvas c=p.getCanvas();Paint title=new Paint(3);title.setColor(Color.rgb(23,53,43));title.setTextSize(18);title.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));c.drawText("OREUM MOK",40,42,title);title.setColor(Color.rgb(174,139,79));title.setStrokeWidth(2);c.drawLine(40,54,555,54,title);float y=80;for(int i=page*per;i<Math.min(lines.size(),(page+1)*per);i++){c.drawText(lines.get(i),40,y,paint);y+=18;}Paint footer=new Paint(3);footer.setTextSize(10);footer.setColor(Color.GRAY);c.drawText("오름목 업무 문서  ·  "+(page+1)+" / "+total,40,810,footer);document.finishPage(p);}ByteArrayOutputStream out=new ByteArrayOutputStream();document.writeTo(out);return out.toByteArray();}finally{document.close();}}}
